  "named": [],
  "about_items": [
    {
      "n": "#386·22",
      "text": "This black fitted top has a sleek cut that hugs your figure without feeling tight, offering a clean line under the coat. Its smooth fabric keeps you warm and polished for an evening in autumn."
    },
    {
      "n": "#97·41",
      "text": "The long quilted coat features a relaxed fit with a belted waist to define your silhouette, and its soft texture adds warmth without bulk. The black color blends seamlessly with your top and shoes for a unified look."
    },
    {
      "n": "#500·03",
      "text": "This white generic bag has a versatile shape that works well as an everyday accessory, carrying essentials with style. Its light color stands out against the darker layers of your outfit for a striking contrast."
    },
    {
      "n": "#186·35",
      "text": "These gold jewelry pieces add a touch of glamour to your look, catching the light at any event. Their shine complements both classic and bold styles without overpowering your outfit."
    }
  ]
}"}

